) values
  ('IE:software-developer','IE','software-developer','Programmers and software development professionals','SOC','SOC 2010','2136','EUR',false,null,null,'profile_ready','2026-08-10',now()),
  ('IE:data-analyst','IE','data-analyst','Data analyst — cross-SOC analytics scope; verified big-data specialist employment retained separately','SOC','SOC 2010',null,'EUR',false,null,null,'profile_ready','2026-08-10',now()),
  ('IE:data-engineer','IE','data-engineer','IT business analysts, architects and systems designers — data engineering / architecture scope','SOC','SOC 2010','2135','EUR',false,null,null,'profile_ready','2026-08-10',now()),
  ('IE:cybersecurity-analyst','IE','cybersecurity-analyst','Information technology and telecommunications professionals n.e.c. — cyber-security analyst scope','SOC','SOC 2010','2139','EUR',false,null,null,'profile_ready','2026-08-10',now()),
  ('IE:network-administrator','IE','network-administrator','IT operations technicians — network administration scope','SOC','SOC 2010','3131','EUR',false,null,null,'profile_ready','2026-08-10',now()),
  ('IE:cloud-engineer','IE','cloud-engineer','Information technology and telecommunications professionals n.e.c. — cloud / DevOps infrastructure engineering scope','SOC','SOC 2010','2139','EUR',false,null,null,'profile_ready','2026-08-10',now()),
