insert into public.country_occupation_metric_snapshots (
  profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,
  shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,
  entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,
  opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at
) values
  ('IE:software-developer','2026-08-10',null,null,null,20,0,0,0,8,0,0,10,5,43,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 2136 Programmers and software development professionals.','shortage_note','SOLAS National Skills Bulletin 2025 directly identifies software developers/engineers as a shortage; 20/20.','visa_basis','SOC 2136 is explicitly on the current Critical Skills Occupations List; 10/10.','growth_boundary','SOLAS reports 9.8% annual average growth for the broad IT occupation group over 2019-2024, but that group rate is not copied into this exact occupation; growth remains 0.','salary_method','No current exact comparable Ireland occupation-level median salary series has been normalised for this cohort; salary remains 0.','entry_basis','Degree and work-based ICT routes exist, but no single entry credential is mandatory across the occupation; 8/15.','entry_burden_basis','No universal statutory professional registration is required; 5/5.'),'2026-08-10'),
  ('IE:data-analyst','2026-08-10',null,null,null,0,0,0,0,8,0,0,8,5,21,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','Canonical Data Analyst spans more than one SOC 2010 context. The current CSEP list explicitly recognises SOC 2423 management consultants/business analysts only when specialising in big-data analytics; the generic title alone is not treated as an exact CSEP match.','shortage_note','SOLAS identifies IT analysts/engineers as a shortage, but generic Data Analyst is broader than that exact group; no direct shortage credit.','visa_basis','Targeted big-data analytics specialist employment under SOC 2423 can qualify for CSEP, so conditional 8/10 rather than universal 10/10.','growth_boundary','Broad IT 9.8% annual average growth is not assigned to this cross-SOC canonical occupation.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','Degree, conversion and analytics pathways exist but no single mandatory entry route; 8/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10'),
  ('IE:data-engineer','2026-08-10',null,null,null,15,0,0,0,8,0,0,10,5,38,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 2135 IT business analysts, architects and systems designers, constrained to data engineering/data architecture work.','shortage_note','SOLAS directly identifies IT analysts/engineers as a shortage. Data Engineer receives strong but not maximum 15/20 because the published shortage label is broader than this exact title.','visa_basis','SOC 2135 is explicitly on the current Critical Skills Occupations List; 10/10.','growth_boundary','Broad IT 9.8% annual average growth is disclosed but not reused as an exact occupation rate.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','Typically degree-level or equivalent technical experience; 8/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10'),
  ('IE:cybersecurity-analyst','2026-08-10',null,null,null,15,0,0,0,8,0,0,10,5,38,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 2139 Information technology and telecommunications professionals n.e.c., cyber-security analyst scope. ONS SOC 2020 later split cyber-security professionals from this SOC 2010 group.','shortage_note','SOLAS IT analysts/engineers shortage supports strong but non-maximal 15/20 for professional cyber analysis; no separate exact cyber shortage count is asserted.','visa_basis','SOC 2139 is explicitly on the current Critical Skills Occupations List; 10/10.','growth_boundary','Broad IT 9.8% annual average growth is not copied into the exact cyber occupation.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','Degree/certification routes and a national Cybersecurity Associate apprenticeship provide structured entry; 8/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10'),
  ('IE:network-administrator','2026-08-10',null,null,null,0,0,0,0,12,0,0,6,5,23,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 3131 IT operations technicians, constrained to network administration. Professional network-engineering roles can fall elsewhere and are not rolled into this technician profile.','shortage_note','The SOLAS shortage summary names software developers/engineers and IT analysts/engineers, not network administrators; 0/20.','visa_basis','SOC 3131 is not on the current Critical Skills list and was not found on the current Ineligible list; ordinary GEP accessibility may apply subject to employer and permit conditions; 6/10.','growth_boundary','Broad IT growth is not treated as an exact network-administrator growth series.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','The national Computer Networking Associate apprenticeship provides a structured work-based route; 12/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10'),
  ('IE:cloud-engineer','2026-08-10',null,null,null,15,0,0,0,8,0,0,10,5,38,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 2139 Information technology and telecommunications professionals n.e.c., constrained to professional cloud/DevOps infrastructure engineering.','shortage_note','SOLAS identifies IT analysts/engineers as a shortage; cloud engineering receives 15/20 because the shortage label is broader than the exact title.','visa_basis','SOC 2139 is explicitly on the current Critical Skills Occupations List; 10/10.','growth_boundary','Broad IT 9.8% annual average growth is not copied into the exact cloud occupation.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','Usually degree-level or equivalent systems/cloud experience; 8/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10'),
  ('IE:database-administrator','2026-08-10',null,null,null,0,0,0,0,8,0,0,6,5,19,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 3131 IT operations technicians, database administration scope. ONS SOC 2020 created a separate Database administrators group from SOC 2010 IT operations technicians.','shortage_note','No exact database-administrator shortage is named in the SOLAS 2025 ICT summary; 0/20.','visa_basis','SOC 3131 is not on the current Critical Skills list and was not found on the current Ineligible list; ordinary GEP accessibility may apply subject to conditions; 6/10.','growth_boundary','Broad IT growth is not assigned as an exact DBA rate.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','Technical/degree routes exist; no single national mandatory pathway; 8/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10'),
  ('IE:ict-support-technician','2026-08-10',null,null,null,0,0,0,0,12,0,0,6,5,23,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 3132 IT user support technicians.','shortage_note','No exact IT user-support shortage is named in the SOLAS 2025 ICT summary; 0/20.','visa_basis','SOC 3132 is not on the current Critical Skills list and was not found on the current Ineligible list; ordinary GEP accessibility may apply subject to conditions; 6/10.','growth_boundary','Broad IT growth is not assigned as an exact support-technician growth rate.','salary_method','No exact comparable Irish median salary series normalised; 0.','entry_basis','Support/network apprenticeships and technical education provide accessible work-based routes; 12/15.','entry_burden_basis','No universal statutory registration; 5/5.'),'2026-08-10')
on conflict (profile_key,as_of_date) do update set
  employment_total=excluded.employment_total,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,
  shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,
  entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,
  opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;

